{"command":"str_replace","path":"/root/uc_solve.py","security_risk":"MEDIUM","summary":"Fix startup tier offline-duration bound constraints","old_str":"        # Startup tier bounds using off[t-1] (consecutive off hours before start at t)
        lags = gen.startup_lags
        for t in range(T):
            off_prev = off_init if t == 0 else off_idx[g, t - 1]
            for kk, lag in enumerate(lags):
                # off_prev >= lag - M*(1-y)
                terms = [(y_idx[g, t, kk], M)]
                if t == 0:
                    add_row(terms, lo=float(lag) - off_prev, hi=INF)
                else:
                    terms.append((off_prev, 1.0))
                    add_row(terms, lo=float(lag), hi=INF)

                # upper bound if not last tier
                if kk + 1 < len(lags):
                    hi_lag = float(lags[kk + 1] - 1)
                    if t == 0:
                        # off_prev <= hi_lag + M*(1-y)  -> off_prev - M*(1-y) <= hi_lag
                        # rearrange: -M*y <= hi_lag - off_prev - M
                        add_row([(y_idx[g, t, kk], -M)], lo=-INF, hi=hi_lag - off_prev - M)
                    else:
                        add_row([(off_prev, 1.0), (y_idx[g, t, kk], -M)], lo=-INF, hi=hi_lag)

